import{_ as e,a as o,b as r,c as a,d as i,e as n,f as s,g as c,h as l,i as p,j as g}from"./chunks/auto-start-4.B7K2fYqk.js";import{_ as m,o as d,c as h,a5 as u}from"./chunks/framework.CcrBcQWS.js";const R=JSON.parse('{"title":"Controller (Steam Deck) and Wi-Fi Connection","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/operation/controller-wifi-connect.md","filePath":"manual/operation/controller-wifi-connect.md","lastUpdated":1787021357000}'),f={name:"manual/operation/controller-wifi-connect.md"};function b(x,t,w,y,_,C){return d(),h("div",null,[...t[0]||(t[0]=[u('<h1 id="controller-steam-deck-and-wi-fi-connection" tabindex="-1">Controller (Steam Deck) and Wi-Fi Connection <a class="header-anchor" href="#controller-steam-deck-and-wi-fi-connection" aria-label="Permalink to &quot;Controller (Steam Deck) and Wi-Fi Connection&quot;">​</a></h1><p>This page describes how to connect the STEAM DECK to the robot Wi-Fi, communicate with the robot in RBQGUI, and proceed through auto start. Complete <a href="./initial-pose.html">Robot Initial Pose Setting</a> (initial pose and power on) first.</p><h2 id="step-1-open-rbqgui-app" tabindex="-1">Step 1: Open RBQGUI app <a class="header-anchor" href="#step-1-open-rbqgui-app" aria-label="Permalink to &quot;Step 1: Open RBQGUI app&quot;">​</a></h2><p>Run the <code>RBQGUI</code> app from the STEAM DECK desktop.</p><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+e+'" alt="RBQGUI app" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ RBQGUI app ]</figcaption></figure><h2 id="step-2-wi-fi-connection" tabindex="-1">Step 2: Wi-Fi connection <a class="header-anchor" href="#step-2-wi-fi-connection" aria-label="Permalink to &quot;Step 2: Wi-Fi connection&quot;">​</a></h2><p>The robot provides a Wi-Fi access point named <code>RBQ_{XX}</code> (XX differs by unit). Connect the STEAM DECK to that network.</p><ol><li><strong>Check Wi-Fi</strong> - After connecting the Steam Deck to the robot AP (<code>RBQ_{XX}</code>), confirm the <strong>top-right</strong> of RBQGUI shows the network name and signal icon.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+o+'" alt="Wi-Fi status in RBQGUI" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Wi-Fi menu ]</figcaption></figure><ol start="2"><li><strong>Select the robot network</strong> - Choose <code>RBQ_{XX}</code> in the list. (If it does not appear, check robot power and Wi-Fi operation.)</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+r+'" alt="Select RBQ_XX network" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Select RBQ_{XX} ]</figcaption></figure><ol start="3"><li><strong>Verify connection</strong> - Confirm the deck shows <strong>Connected</strong> to <code>RBQ_{XX}</code>.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+a+'" alt="RBQ_XX connected" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Wi-Fi connected ]</figcaption></figure><h2 id="step-3-connect-steam-deck-and-robot" tabindex="-1">Step 3: Connect STEAM DECK and robot <a class="header-anchor" href="#step-3-connect-steam-deck-and-robot" aria-label="Permalink to &quot;Step 3: Connect STEAM DECK and robot&quot;">​</a></h2><p>For RBQGUI to talk to the robot, you must also establish remote controller-robot communication inside the app.</p><ol><li><strong>Open the connection dialog</strong> - Press <code>Remote Controller-Robot Communication Connection</code> (orange) on the left of the top bar. A connection pop-up appears.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+i+'" alt="Remote controller-robot communication connection" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Communication connection button and pop-up ]</figcaption></figure><ol start="2"><li><strong>Connect</strong> - In the pop-up, press <code>Connect</code> to attempt communication with the robot.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+n+'" alt="Connect button" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Connect ]</figcaption></figure><ol start="3"><li><strong>Confirm result</strong> - When connected, <code>Remote Controller-Robot Communication Connection</code> at the same position turns <strong>green</strong>, and the pop-up shows a connected state.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+s+'" alt="Connected to robot" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Connected (button green) ]</figcaption></figure><h2 id="auto-start" tabindex="-1">Step 4: Auto start <a class="header-anchor" href="#auto-start" aria-label="Permalink to &quot;Step 4: Auto start {#auto-start}&quot;">​</a></h2><p>To bring up robot software and state in one flow, use the auto start procedure.</p><ol><li><strong>Open initial setup</strong> - Press <code>Robot Initial Setup</code> (red) on the left of the top bar.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+c+'" alt="Robot Initial Setup" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Robot Initial Setup button ]</figcaption></figure><ol start="2"><li><strong>Run auto start</strong> - In the pop-up, press <code>Auto Start Robot</code>. After a short wait, progress appears on screen.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+l+'" alt="Auto Start Robot" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Auto Start Robot ]</figcaption></figure><ol start="3"><li><strong>Check progress</strong> - Confirm each item such as <code>Manual Setup</code> updates. (Some items may show green before others for a while.)</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+p+'" alt="Auto start in progress" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Auto start in progress ]</figcaption></figure><ol start="4"><li><strong>Confirm completion</strong> - When <strong>all</strong> setup items shown on screen are <strong>green</strong>, auto start has completed successfully.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+g+'" alt="Auto start complete" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Auto start complete (all green) ]</figcaption></figure><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>If, after auto start, not all setup items turn green or an error is shown, confirm no people are nearby, review the <a href="../Safety/emergency-stop-procedures">emergency stop procedures</a>, then follow the steps below. Before operation, always comply with the <a href="../Safety/general-safety-warning-precautions">general safety guidelines</a>.</p><ol style="margin:0.5rem 0 0 1.25rem;"><li>If <code>Check CAN-Bus</code> fails: power off the robot safely, then restart.</li><li>If <code>Find Home-pose</code> fails: on a flat, stable surface per <a href="../Safety/maintenance-safety">maintenance safety</a>, check leg pose, then restart.</li></ol><p style="margin-top:0.75rem;">If the problem persists, contact Rainbow Robotics via <a href="../Troubleshooting/error-reporting">error reporting</a>.</p></div></div>',32)])])}const v=m(f,[["render",b]]);export{R as __pageData,v as default};
